contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}

    function run(address adr, uint fund) public payable {
        require(address(this).balance >= fund);
        require(fund > 0);
        // Fund c by having the owner (this test contract) call multiplicate with
        // recipient c itself; this never reverts and leaves c with Ether.
        c.multiplicate{value: fund}(address(c));
        uint balBefore = address(c).balance;
        require(balBefore > 0);

        // Owner call to Command with empty data forwards no value.
        bool reverted;
        try c.Command(adr, "") { reverted = false; } catch { reverted = true; }

        // The call must never revert for the owner, and since msg.value is 0,
        // the contract's balance is exactly unchanged regardless of whether
        // the recipient accepts Ether or not.
        assert(!reverted && address(c).balance == balBefore);
    }
}

